// ── Extract alert fields from Supabase webhook payload ──────────
// Supabase DB webhooks send the payload in this shape:
// { "type": "INSERT", "table": "grain_alerts", "record": { ... } }

const body = $input.first().json.body || $input.first().json;
const record = body.record || body;

// Pull all the fields we need from the alert record
const alertId     = record.alert_id    || record.id || 'unknown';
const adminId     = record.admin_id    || '';
const siloId      = record.silo_id     || 'Unknown Silo';
const title       = record.title       || 'Grain Alert';
const message     = record.message     || '';
const priority    = record.priority    || 'medium';
const sensorType  = record.sensor_type || '';
const triggerCond = record.trigger_conditions || {};
const warehouseId = record.warehouse_id || null;
const batchId     = record.batch_id    || null;

// Extract sensor reading value from trigger_conditions JSON
const metricValue = triggerCond.value     || null;
const threshold   = triggerCond.threshold || null;
const metric      = triggerCond.metric    || sensorType;

// Map priority to notification severity level used in the notifications table
const severityMap = {
  critical: 'critical',
  high:     'high',
  medium:   'medium',
  low:      'low',
};
const severity = severityMap[priority] || 'medium';

// Build a short summary line for the notification
let summary = message;
if (metricValue !== null && threshold !== null) {
  summary = `${title}: ${metric} reading ${metricValue} exceeded threshold ${threshold}`;
}

return [{
  json: {
    alertId,
    adminId,
    siloId,
    warehouseId,
    batchId,
    title,
    message,
    summary,
    priority,
    severity,
    sensorType,
    metric,
    metricValue,
    threshold,
    triggeredAt: new Date().toISOString(),
  }
}];
